                            ]]]
                            or (
                                //IMPORT[DOT[STAR and DOT[
                                    IDENT[@text = 'annotations'] and DOT[IDENT[@text = 'ibatis'] and DOT[IDENT[@text = 'org'] and IDENT[@text = 'apache']]]
                                ]]]
                                and not(//IMPORT[DOT/IDENT[@text = $name]])
                            )
                        )
                    )
